var N=15;
function gmNew(){ var g=[]; for(var r=0;r<N;r++){ g.push(new Array(N).fill(0)); } return g; }
function gmClone(g){ return g.map(function(r){ return r.slice(); }); }
function gmIn(x,y){ return x>=0&&x<N&&y>=0&&y<N; }
function gmWin(board, x, y, p){
  var dirs=[[1,0],[0,1],[1,1],[1,-1]];
  for(var d=0;d<4;d++){
    var dx=dirs[d][0], dy=dirs[d][1], cnt=1, i;
    for(i=1;i<5;i++){ var nx=x+dx*i, ny=y+dy*i; if(gmIn(nx,ny)&&board[ny][nx]===p) cnt++; else break; }
    for(i=1;i<5;i++){ var nx=x-dx*i, ny=y-dy*i; if(gmIn(nx,ny)&&board[ny][nx]===p) cnt++; else break; }
    if(cnt>=5) return true;
  }
  return false;
}
function gmPlace(board, x, y, p){ var g=gmClone(board); g[y][x]=p; return g; }
function gmScorePoint(board, x, y, p){
  var dirs=[[1,0],[0,1],[1,1],[1,-1]], score=0;
  for(var d=0;d<4;d++){
    var dx=dirs[d][0], dy=dirs[d][1], cnt=1, empty=0, i;
    for(i=1;i<5;i++){ var nx=x+dx*i, ny=y+dy*i; if(!gmIn(nx,ny)) break; var v=board[ny][nx]; if(v===p) cnt++; else if(v===0){ empty++; break; } else break; }
    for(i=1;i<5;i++){ var nx=x-dx*i, ny=y-dy*i; if(!gmIn(nx,ny)) break; var v=board[ny][nx]; if(v===p) cnt++; else if(v===0){ empty++; break; } else break; }
    if(cnt>=5) score+=100000; else if(cnt===4&&empty>=1) score+=10000; else if(cnt===3&&empty>=1) score+=1000; else if(cnt===2&&empty>=1) score+=100;
  }
  return score;
}
function gmAi(board, ai, human){
  var best=null, bestScore=-1, win=null, block=null;
  for(var y=0;y<N;y++) for(var x=0;x<N;x++){
    if(board[y][x]!==0) continue;
    if(gmWin(gmPlace(board,x,y,ai), x, y, ai)){ win=[x,y]; }
    if(gmWin(gmPlace(board,x,y,human), x, y, human)){ block=[x,y]; }
  }
  if(win) return win;
  if(block) return block;
  for(var y=0;y<N;y++) for(var x=0;x<N;x++){
    if(board[y][x]!==0) continue;
    var s=gmScorePoint(board,x,y,ai)+gmScorePoint(board,x,y,human)*0.9;
    if(s>bestScore){ bestScore=s; best=[x,y]; }
  }
  return best || [7,7];
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { N:N, gmNew:gmNew, gmClone:gmClone, gmIn:gmIn, gmWin:gmWin, gmPlace:gmPlace, gmScorePoint:gmScorePoint, gmAi:gmAi };
}
if (typeof window !== 'undefined') {
  window.GomokuForgePure = { N:N, gmNew:gmNew, gmClone:gmClone, gmIn:gmIn, gmWin:gmWin, gmPlace:gmPlace, gmScorePoint:gmScorePoint, gmAi:gmAi };
}
